private def combineResults(
    primary: Map[UUID, ResultEntity],
    additional: Map[UUID, ResultEntity],
    uuids: Iterable[UUID],
): Map[UUID, List[ResultEntity]] = {
  uuids.flatMap { uuid =>
    (primary.get(uuid), additional.get(uuid)) match {
      case (Some(res), Some(add)) =>
        Some(uuid -> List(res, add))
      case (Some(res), None) =>
        Some(uuid -> List(res))
      case _ => None
    }
  }.toMap
}

